// Three helpers of one shape: each takes a callback. The contract closes
// `callbacks` for `runClosed` (it never calls its argument) and leaves it open
// for `runFirst` and `runSecond`.
//
// The signatures are `tsc`-clean for every call the fixture makes, so nothing
// here duplicates a type diagnostic.
export declare function runClosed(callback: () => void): void;
export declare function runFirst(callback: () => void): void;
export declare function runSecond(callback: () => void): void;
